-- Declared foreign keys for learning module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('learning.course_enrollments') IS NOT NULL AND to_regclass('learning.courses') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('learning.course_enrollments') AND c.contype = 'f' AND a.attname = 'course_id'
    ) THEN
        ALTER TABLE learning.course_enrollments ADD CONSTRAINT fk_course_enrollments_course_id FOREIGN KEY (course_id) REFERENCES learning.courses (id) NOT VALID;
        BEGIN
            ALTER TABLE learning.course_enrollments VALIDATE CONSTRAINT fk_course_enrollments_course_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_course_enrollments_course_id left NOT VALID: stored rows of learning.course_enrollments reference missing rows';
        END;
    END IF;
END $$;

